'use client';
import { Clock, CheckCircle, Smartphone } from 'lucide-react';

export default function OrdersPage() {
    const activeOrders = [
        { id: '#8821', items: ['Chicken Biryani x1', 'Coke x2'], total: '₹350', status: 'Cooking', time: '10 mins ago' },
        { id: '#8822', items: ['Veg Pizza x1'], total: '₹220', status: 'Pending', time: 'Just now' },
    ];

    return (
        <div className="p-4 space-y-4">
            <h1 className="text-2xl font-bold text-gray-900">Orders</h1>

            <div className="flex gap-2 mb-2 overflow-x-auto pb-2">
                <button className="bg-primary text-white px-4 py-2 rounded-full text-sm font-bold shadow-md shadow-orange-200 whitespace-nowrap">Active (3)</button>
                <button className="bg-white text-gray-600 border border-gray-200 px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap">Ready (1)</button>
                <button className="bg-white text-gray-600 border border-gray-200 px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap">Past Orders</button>
            </div>

            <div className="space-y-4">
                {activeOrders.map((order) => (
                    <div key={order.id} className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm relative overflow-hidden">
                        {order.status === 'Pending' && (
                            <div className="absolute top-0 right-0 bg-yellow-400 text-yellow-900 text-[10px] font-bold px-2 py-1 rounded-bl-lg">
                                NEW
                            </div>
                        )}

                        <div className="flex justify-between items-start mb-3">
                            <div>
                                <h3 className="font-bold text-lg text-gray-900">{order.id}</h3>
                                <p className="text-xs text-gray-500 flex items-center gap-1">
                                    <Clock size={12} /> {order.time}
                                </p>
                            </div>
                            <p className="font-bold text-primary">{order.total}</p>
                        </div>

                        <div className="bg-gray-50 p-3 rounded-lg mb-4 space-y-1">
                            {order.items.map((item, idx) => (
                                <p key={idx} className="text-sm text-gray-700 font-medium">• {item}</p>
                            ))}
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            {order.status === 'Pending' ? (
                                <>
                                    <button className="bg-red-50 text-red-600 py-2.5 rounded-lg font-bold text-sm">Reject</button>
                                    <button className="bg-green-600 text-white py-2.5 rounded-lg font-bold text-sm shadow-md shadow-green-200">Accept</button>
                                </>
                            ) : (
                                <button className="col-span-2 bg-primary text-white py-2.5 rounded-lg font-bold text-sm flex items-center justify-center gap-2">
                                    <CheckCircle size={18} /> Mark as Ready
                                </button>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
